class Solution {
public:
    int badSensor(vector<int>& sensor1, vector<int>& sensor2) {
        int n = sensor1.size();
        int i = 0;
        while (i < n && sensor1[i] == sensor2[i]) i++;
        if (i >= n - 1) return -1;

        bool s1Drop = true;
        for (int j = i; j < n - 1; j++) {
            if (sensor1[j] != sensor2[j + 1]) {
                s1Drop = false;
                break;
            }
        }

        bool s2Drop = true;
        for (int j = i; j < n - 1; j++) {
            if (sensor2[j] != sensor1[j + 1]) {
                s2Drop = false;
                break;
            }
        }

        if (s1Drop && s2Drop) return -1;
        if (s1Drop) return 1;
        if (s2Drop) return 2;
        return -1;
    }
};

